-- ==========================================
-- ArenaSync Supabase PostgreSQL Schema & Seed
-- ==========================================

-- 1. Create Tables
CREATE TABLE IF NOT EXISTS sports (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  image TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS tournaments (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  sport_id BIGINT REFERENCES sports(id) ON DELETE SET NULL,
  location TEXT,
  state TEXT,
  district TEXT,
  ground_name TEXT,
  date DATE,
  last_registration_date DATE,
  entry_fee NUMERIC DEFAULT 0,
  prize_amount NUMERIC DEFAULT 0,
  max_teams INTEGER DEFAULT 16,
  registered_teams INTEGER DEFAULT 0,
  status TEXT DEFAULT 'upcoming',
  description TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS teams (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  tournament_id BIGINT REFERENCES tournaments(id) ON DELETE CASCADE,
  "group" TEXT,
  members INTEGER DEFAULT 11,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Indexes for Performance
CREATE INDEX IF NOT EXISTS idx_tournaments_sport_id ON tournaments(sport_id);
CREATE INDEX IF NOT EXISTS idx_tournaments_status ON tournaments(status);
CREATE INDEX IF NOT EXISTS idx_tournaments_date ON tournaments(date);
CREATE INDEX IF NOT EXISTS idx_teams_tournament_id ON teams(tournament_id);

-- 3. Row Level Security (RLS) Policies
ALTER TABLE sports ENABLE ROW LEVEL SECURITY;
ALTER TABLE tournaments ENABLE ROW LEVEL SECURITY;
ALTER TABLE teams ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read access on sports" ON sports FOR SELECT USING (true);
CREATE POLICY "Allow public read access on tournaments" ON tournaments FOR SELECT USING (true);
CREATE POLICY "Allow public read access on teams" ON teams FOR SELECT USING (true);

CREATE POLICY "Allow insert on tournaments" ON tournaments FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow update on tournaments" ON tournaments FOR UPDATE USING (true);
CREATE POLICY "Allow insert on teams" ON teams FOR INSERT WITH CHECK (true);

-- 4. Seed Data: Sports (10 rows)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, image = EXCLUDED.image;

SELECT setval('sports_id_seq', (SELECT MAX(id) FROM sports));

-- 5. Seed Data: Tournaments (150 rows)
ON CONFLICT (id) DO UPDATE SET 
  name = EXCLUDED.name, sport_id = EXCLUDED.sport_id, location = EXCLUDED.location,
  state = EXCLUDED.state, district = EXCLUDED.district, ground_name = EXCLUDED.ground_name,
  date = EXCLUDED.date, last_registration_date = EXCLUDED.last_registration_date,
  entry_fee = EXCLUDED.entry_fee, prize_amount = EXCLUDED.prize_amount,
  max_teams = EXCLUDED.max_teams, registered_teams = EXCLUDED.registered_teams,
  status = EXCLUDED.status, description = EXCLUDED.description;

SELECT setval('tournaments_id_seq', (SELECT MAX(id) FROM tournaments));
